661	func TestSubmitReviewSaveFailureRetriedAfterRecovery(t *testing.T) {
662		dir := t.TempDir()
663		mustReplay(t, dir, twoFindingsInput)
664	
665		// A pre-existing alert record must survive the failed and successful
666		// submissions byte-for-byte in content.
667		alertsBefore, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
668		if err != nil {
669			t.Fatal(err)
670		}
671		if len(alertsBefore) != 2 {
672			t.Fatalf("setup: got %d alert records, want 2", len(alertsBefore))
673		}
674	
675		// Main precondition: the object is at version 1 with a real judgment and
676		// one complete revision.
677		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
678		if !first.Created || first.Version != 1 {
679			t.Fatalf("setup submission = %+v", first)
680		}
681	
682		original, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
683		if err != nil {
684			t.Fatal(err)
685		}
686		if original.Status != ReviewStatusReal || original.Version != 1 || len(original.Revisions) != 1 {
687			t.Fatalf("setup object state = %+v", original)
688		}
689		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
690		if err != nil {
691			t.Fatal(err)
692		}
693	
694		// Valid target, valid content, valid expected version: the only failure
695		// is storage failing while the new revision is being archived.
696		breakArchiveSave(t, dir)
697		rejudgment := reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually a false positive", ReviewStatusFalsePositive, 1)
698		failed, err := SubmitReview(dir, rejudgment)
699		if err == nil {
700			t.Fatalf("save failure must return an error, got result %+v", failed)
701		}
702		if errors.Is(err, ErrBusy) || errors.Is(err, ErrReviewConflict) ||
703			errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrSubmissionConflict) {
704			t.Fatalf("failure must happen at the save stage, got %v", err)
705		}
706		if failed.Created {
707			t.Fatalf("failed save must not report created=true: %+v", failed)
708		}
709		restoreArchiveSave(t, dir)
710	
711		// The original judgment is fully retained: still real at version 1, the
712		// single original revision with no trace of the failed submission.
713		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
714		if err != nil {
715			t.Fatal(err)
716		}
717		if after.Status != ReviewStatusReal || after.Version != 1 {
718			t.Fatalf("failed save advanced the object: %q/%d, want real/1", after.Status, after.Version)
719		}
720		if len(after.Revisions) != 1 {
721			t.Fatalf("failed save left %d revisions: %+v", len(after.Revisions), after.Revisions)
722		}
723		if !reflect.DeepEqual(after.Revisions[0], original.Revisions[0]) {
724			t.Fatalf("original revision changed: %+v, want %+v", after.Revisions[0], original.Revisions[0])
725		}
726		for _, rev := range after.Revisions {
727			if rev.SubmissionID == "s-2" || rev.Operator == "bob" ||
728				rev.Status == ReviewStatusFalsePositive || rev.Reason == "actually a false positive" {
729				t.Fatalf("failed submission content leaked into history: %+v", rev)
730			}
731		}
732		// The archived original conclusion, its detection version and the raw
733		// swap evidence are untouched, as are the pre-existing alert records.
734		if after.Original == nil ||
735			after.Original.Finding.TxHash != "0xv" || after.Original.Finding.Kind != "sandwich" ||
736			after.Original.Finding.Severity != 3 || len(after.Original.Finding.Evidence) != 3 {
737			t.Fatalf("original conclusion/evidence changed: %+v", after.Original)
738		}
739		if after.Original.Version.ID != BuiltinVersionID {
740			t.Fatalf("detection version changed: %+v", after.Original.Version)
741		}
742		archiveAfter, err := os.ReadFile(filepath.Join(dir, archiveFileName))
743		if err != nil {
744			t.Fatal(err)
745		}
746		if !reflect.DeepEqual(archiveBefore, archiveAfter) {
747			t.Fatal("failed save modified the archive file")
748		}
749		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
750		if err != nil {
751			t.Fatal(err)
752		}
753		if !reflect.DeepEqual(alertsBefore, alertsAfter) {
754			t.Fatalf("alert records changed: before %+v after %+v", alertsBefore, alertsAfter)
755		}
756	
757		// Storage recovered: the exact same submission, same submissionId and
758		// still expectedVersion 1, goes through as a fresh create — the failed
759		// attempt must neither have consumed the submission id nor count as a
760		// stored duplicate.
761		retry, err := SubmitReview(dir, rejudgment)
762		if err != nil {
763			t.Fatalf("retry after recovery: %v", err)
764		}
765		if !retry.Created || retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
766			t.Fatalf("retry = %+v, want created=true at version 2", retry)
767		}
768		wantRev := rejudgment.revision(2)
769		if !reflect.DeepEqual(retry.Revision, wantRev) {
770			t.Fatalf("saved revision = %+v, want %+v", retry.Revision, wantRev)
771		}
772	
773		saved, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
774		if err != nil {
775			t.Fatal(err)
776		}
777		if saved.Status != ReviewStatusFalsePositive || saved.Version != 2 || len(saved.Revisions) != 2 {
778			t.Fatalf("object after retry = %q/%d with %d revisions", saved.Status, saved.Version, len(saved.Revisions))
779		}
780		if !reflect.DeepEqual(saved.Revisions[0], original.Revisions[0]) {
781			t.Fatalf("original revision not retained first: %+v", saved.Revisions[0])
782		}
783		if !reflect.DeepEqual(saved.Revisions[1], wantRev) {
784			t.Fatalf("appended revision = %+v, want %+v", saved.Revisions[1], wantRev)
785		}
786	
787		// Sending the now-successful submission verbatim a second time is the
788		// ordinary idempotent retry: created:false, the first successfully saved
789		// revision returned, history unchanged.
790		again, err := SubmitReview(dir, rejudgment)
791		if err != nil {
792			t.Fatalf("verbatim resend: %v", err)
793		}
794		if again.Created {
795			t.Fatal("verbatim resend of a stored submission must report created=false")
796		}
797		if !reflect.DeepEqual(again.Revision, wantRev) || again.Version != 2 || again.Status != ReviewStatusFalsePositive {
798			t.Fatalf("resend result = %+v", again)
799		}
800		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
801		if err != nil {
802			t.Fatal(err)
803		}
