		}(i)
	}
	close(start)
	wg.Wait()

	succeeded, busy, other := 0, 0, 0
	for _, err := range errs {
		switch {
		case err == nil:
			succeeded++
		case errors.Is(err, ErrBusy):
			busy++
		default:
			other++
			t.Errorf("unexpected error: %v", err)
		}
	}
	if other != 0 {
